using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Credit;
using Shop.Modules.Sales;
using Shop.Modules.Inventory;
using Shop.SharedKernel;
using Xunit;
using IdentityContext=Shop.Modules.Identity.IdentityDbContext;
namespace Shop.SqlTests;
public sealed class ChequeReviewHoldSqlTests():CreditRequirementsSqlBase(new SqlFixture()),IAsyncLifetime
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private const string Base="/api/admin/credit/review-hold-policy";
    private static string V(JsonNode n,string k)=>CreditCheckoutQuoteQa.Text(n,k);
    private static async Task<JsonNode> Read(HttpResponseMessage response){using(response){var raw=await response.Content.ReadAsStringAsync();Assert.True(response.IsSuccessStatusCode,$"HTTP{(int)response.StatusCode}: {raw}");Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_CHEQUE_REVIEW_HOLD_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=response.RequestMessage!.Method.Method,path=response.RequestMessage.RequestUri!.PathAndQuery}));}return JsonNode.Parse(raw)!;}}
    private static CreditOrderInput Order(JsonNode q,string? policy=null)=>new(V(q,"id"),V(q,"fingerprint"),"Synthetic review hold QA","09100000000",new("IR","تهران","تهران","Synthetic QA only; no actual delivery","1234567890"),"No actual person or funds",true,true,policy);
    private static Task<JsonNode> Write(HttpClient f,ChequeReviewHoldInput input,string? cmd=null)=>ReadPost(f,Base+"/commands/"+(cmd??Id()),input);
    private static async Task<JsonNode> ReadPost<T>(HttpClient f,string path,T body)=>await Read(await f.PostAsJsonAsync(path,body));
    [Fact]public async Task ExplicitPolicyAppliesOnlyToNewAcceptedOrdersAndKeepsOldPayloadReceiptsAndDeadlines()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var helper=new CreditOrderSqlTests(sql);var first=await helper.Ready(f,reviewer);using var oldCustomer=first.Customer;var unset=await Read(await f.GetAsync(Base));Assert.Null(unset["version"]);Assert.Null(unset["current"]);var legacyCmd=Id();var legacyInput=Order(first.Quote);var legacy=await ReadPost(oldCustomer,"/api/credit-orders/commands/"+legacyCmd,legacyInput);var legacyExpiry=V(legacy["order"]!["summary"]!,"expiresAt");Assert.Null(legacy["reviewHold"]);
        var enabled=await Write(f,new("Enable",null,60,true));var version=V(enabled["policy"]!,"version");var legacyReplay=await ReadPost(oldCustomer,"/api/credit-orders/commands/"+legacyCmd,legacyInput);Assert.True(legacyReplay["replayed"]!.GetValue<bool>());Assert.Equal(legacy["order"]!.ToJsonString(),legacyReplay["order"]!.ToJsonString());Assert.Equal(legacyExpiry,V((await Read(await oldCustomer.GetAsync("/api/credit-orders/commands/"+legacyCmd)))["order"]!["summary"]!,"expiresAt"));
        var next=await helper.Ready(f,reviewer,first.Goods);using var customer=next.Customer;var readiness=await Read(await customer.GetAsync("/api/credit-orders/quotes/"+V(next.Quote,"id")+"/readiness"));Assert.Equal(version,V(readiness["reviewHold"]!,"policyVersion"));Assert.Equal(60,readiness["reviewHold"]!["maximumMinutes"]!.GetValue<int>());using(var stale=await customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),Order(next.Quote)))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var cmd=Id();var input=Order(next.Quote,version);var made=await ReadPost(customer,"/api/credit-orders/commands/"+cmd,input);var expiry=DateTimeOffset.Parse(V(made["order"]!["summary"]!,"expiresAt"));Assert.True(expiry>DateTimeOffset.Parse(V(next.Quote,"expiresAt")).AddMinutes(40));Assert.Equal(version,V(made["reviewHold"]!,"policyVersion"));Assert.Equal(expiry,made["reviewHold"]!["expiresAt"]!.GetValue<DateTimeOffset>());
        await Write(f,new("Disable",version,null,true));var replay=await ReadPost(customer,"/api/credit-orders/commands/"+cmd,input);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(made["reviewHold"]!.ToJsonString(),replay["reviewHold"]!.ToJsonString());var detail=await Read(await customer.GetAsync("/api/credit-orders/"+V(made["order"]!["summary"]!,"id")));Assert.Equal(made["reviewHold"]!.ToJsonString(),detail["reviewHold"]!.ToJsonString());await ReadPost(customer,"/api/orders/v2/"+V(made["order"]!["summary"]!,"id")+"/cancel",new{version=V(made["order"]!["summary"]!,"version")});await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.Single(await db.CreditOrderReviewHolds.ToArrayAsync());Assert.Equal(DateTimeOffset.Parse(legacyExpiry),(await db.Orders.SingleAsync(x=>x.Id==V(legacy["order"]!["summary"]!,"id"))).ExpiresAt);Assert.Equal(2,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.CountAsync());
    }
    [Fact]public async Task AuditedConfigurationRollsBackReplaysOnceAndCompetingVersionsCannotBothWin()
    {
        using var f=await Staff("FinanceManager");var cmd=Id();var input=new ChequeReviewHoldInput("Enable",null,60,true);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_HoldAudit CHECK ([Action]<>'SALES_CHEQUE_REVIEW_HOLD_ENABLE')");try{using var bad=await f.PostAsJsonAsync(Base+"/commands/"+cmd,input);Assert.Equal(HttpStatusCode.Conflict,bad.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_HoldAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.False(await db.ChequeReviewHoldPolicies.AnyAsync());Assert.False(await db.ChequeReviewHoldRevisions.AnyAsync());Assert.False(await db.ChequeReviewHoldCommands.AnyAsync());}
        var both=await Task.WhenAll((await Task.WhenAll(f.PostAsJsonAsync(Base+"/commands/"+cmd,input),f.PostAsJsonAsync(Base+"/commands/"+cmd,input))).Select(Read));Assert.Single(both,x=>x["replayed"]!.GetValue<bool>());var version=V(both[0]["policy"]!,"version");var race=await Task.WhenAll(f.PostAsJsonAsync(Base+"/commands/"+Id(),new ChequeReviewHoldInput("Enable",version,30,true)),f.PostAsJsonAsync(Base+"/commands/"+Id(),new ChequeReviewHoldInput("Disable",version,null,true)));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();using(var conflict=await f.PostAsJsonAsync(Base+"/commands/"+cmd,input with{Minutes=15}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);Assert.True((await Read(await f.GetAsync(Base+"/commands/"+cmd)))["replayed"]!.GetValue<bool>());Assert.Equal(2,(await Read(await f.GetAsync(Base+"/history")))["items"]!.AsArray().Count);
    }
    [Fact]public async Task StrictFinanceAuthorityImmutableHistoryForeignKeysAndTamperingFailClosed()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var owner=await Customer();using var customer=owner.Client;foreach(var denied in new[]{reviewer,sales,customer}){using var r=await denied.GetAsync(Base);Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);}using(var query=await f.GetAsync(Base+"/history?beforeRevision=01"))Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);using(var forged=await f.PostAsJsonAsync(Base+"/commands/"+Id(),new{action="Enable",version=(string?)null,minutes=60,confirmed=true,cashReservationMinutes=60}))Assert.Equal(HttpStatusCode.BadRequest,forged.StatusCode);
        var cmd=Id();var enabled=await Write(f,new("Enable",null,60,true),cmd);await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SalesDbContext>();var head=await db.ChequeReviewHoldPolicies.SingleAsync();head.PublishedRevisionId=null;Assert.Equal("cheque_review_hold_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [sales].[ChequeReviewHoldPolicies] SET [PublishedRevisionId]={Id()} WHERE [Id]=1"));await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027120833_CreditOrderLinks"));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [sales].[ChequeReviewHoldCommands] SET [ResultHash]={new string('0',64)} WHERE [CommandId]={cmd}");}using(var corrupt=await f.GetAsync(Base))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);using(var corrupt=await f.GetAsync(Base+"/commands/"+cmd))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);
    }
    private sealed class MovingClock(DateTimeOffset at):TimeProvider{private DateTimeOffset now=at;public override DateTimeOffset GetUtcNow()=>now;public void Advance()=>now=now.AddMinutes(6);}
    private sealed class DelayedStock(IStockBoundedReservations inner,MovingClock clock):IStockBoundedReservations{public async Task<StockReservationData> HoldBoundedAsync(StockBoundedHoldRequest r,CancellationToken ct){var held=await inner.HoldBoundedAsync(r,ct);clock.Advance();return held;}}
    [Fact]public async Task LongerReviewHoldNeverExtendsPriceValidityDuringOrderCreation()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(f,reviewer);using var customer=s.Customer;var enabled=await Write(f,new("Enable",null,60,true));var clock=new MovingClock(DateTimeOffset.UtcNow);using var delayed=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>{services.AddSingleton<TimeProvider>(clock);services.AddScoped<IStockBoundedReservations>(sp=>new DelayedStock(new StockReservationService(sp.GetRequiredService<InventoryDbContext>(),clock,true),clock));}));using var client=delayed.CreateClient(new(){HandleCookies=false});foreach(var h in customer.DefaultRequestHeaders)client.DefaultRequestHeaders.TryAddWithoutValidation(h.Key,h.Value);using var expired=await client.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),Order(s.Quote,V(enabled["policy"]!,"version")));Assert.Equal(HttpStatusCode.Conflict,expired.StatusCode);await using var scope=sql.Factory.Services.CreateAsyncScope();Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.AnyAsync());Assert.False(await scope.ServiceProvider.GetRequiredService<SalesDbContext>().CreditOrderReviewHolds.AnyAsync());Assert.False(await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync());Assert.Equal(0,(await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Goods.Variant)).Reserved);
    }
}
